UserObject.plantUmlData:
{
  "data": "@startuml
skinparam conditionStyle inside
skinparam sequenceMessageAlign center
skinparam shadowing false
skinparam defaultTextAlignment center

title Activity Diagram - Luồng Đặt Món và Thanh Toán (End-to-End)

|#LightYellow|Khách hàng (Customer)|
|#LightCyan|Hệ thống (Web/API Backend)|
|#LightGreen|Bếp / Pha chế (Kitchen)|
|#Pink|Đơn vị Vận chuyển / Phục vụ|

|Khách hàng (Customer)|
start
:Truy cập hệ thống và xem Thực đơn;
:Chọn món ăn và tùy chọn (size, topping...);
:Thêm món vào Giỏ hàng;
:Xem giỏ hàng và chọn "Tiến hành Đặt đơn";

|Hệ thống (Web/API Backend)|
:Kiểm tra trạng thái đăng nhập;
if (Người dùng đã đăng nhập?) then ([Chưa đăng nhập])
    |Khách hàng (Customer)|
    :Chuyển hướng đến màn hình Đăng nhập;
    repeat
        :Nhập thông tin xác thực (Email/Mật khẩu);
        |Hệ thống (Web/API Backend)|
        :Xác thực thông tin tài khoản;
    backward:Báo lỗi đăng nhập;
    repeat while (Thông tin đăng nhập hợp lệ?) is ([Không]) not ([Hợp lệ])
    |Khách hàng (Customer)|
    :Đăng nhập thành công, quay lại Giỏ hàng;
else ([Đã đăng nhập])
endif

|Hệ thống (Web/API Backend)|
:Kiểm tra tồn kho & khả dụng của các món;
if (Tất cả món còn hàng?) then ([Còn thiếu / Hết món])
    :Thông báo món đã hết hoặc không đủ số lượng;
    |Khách hàng (Customer)|
    :Cập nhật hoặc chọn lại món khác trong giỏ hàng;
    detach
else ([Đủ hàng / Khả dụng])
endif

|Khách hàng (Customer)|
:Xác nhận thông tin giao hàng & chọn cổng thanh toán;
note right
    Hỗ trợ các cổng:
    - MoMo
    - VNPay
    - Stripe / Thẻ
end note

repeat
    |Khách hàng (Customer)|
    :Thực hiện thanh toán qua cổng đã chọn;
    |Hệ thống (Web/API Backend)|
    :Xác thực và ghi nhận kết quả từ Cổng thanh toán;

    if (Trạng thái giao dịch?) then ([Thành công])
        break
    else ([Thất bại])
        |Khách hàng (Customer)|
        :Nhận thông báo thanh toán thất bại;
        if (Khách hàng muốn thử lại?) then ([Thử lại / Đổi cổng khác])
            :Chọn lại phương thức thanh toán;
        else ([Hủy đơn])
            |Hệ thống (Web/API Backend)|
            :Hủy phiên giao dịch;
            |Khách hàng (Customer)|
            stop
        endif
    endif
repeat while (Thực hiện lại giao dịch)

|Hệ thống (Web/API Backend)|
:Tạo Đơn hàng và lưu vào cơ sở dữ liệu (Database);
:Trừ số lượng tồn kho (Inventory Deduct);
:Gửi thông báo Đặt hàng thành công cho Khách hàng;

fork
    |Bếp / Pha chế (Kitchen)|
    :Nhận phiếu chế biến món (KDS/In bếp);
    :Chuẩn bị và hoàn thành món ăn;
    :Cập nhật trạng thái "Sẵn sàng phục vụ / giao";
fork again
    |Khách hàng (Customer)|
    :Theo dõi tiến độ đơn hàng trên giao diện;
end fork

|Đơn vị Vận chuyển / Phục vụ|
:Nhận món và giao đến khách hàng;

|Khách hàng (Customer)|
:Nhận món ăn & kiểm tra đơn hàng;
:Hoàn tất đơn hàng;
stop

@enduml",
  "config": null
}
